import sys

def main():
    n, w, h = map(int, sys.stdin.read().split()[:3])
    lo, hi = 1, n * max(w, h)
    while lo < hi:
        mid = (lo + hi) // 2
        if (mid // w) * (mid // h) >= n:
            hi = mid
        else:
            lo = mid + 1
    print(lo)

